## Solution
```cpp[]
class Solution {
public:
    int findDuplicate(vector<int>& nums) {
        // number whose frequency is more than 1
        int n = nums.size();
        int max_ = nums[0];

        // for hash array size
        for(int i = 0 ;i<n; i++){
            max_ = max(max_, nums[i]);
        }

        // precompute stage
        vector<int> hash(max_ + 1, 0);
        for(int i = 0; i<n; i++){
            hash[nums[i]]++;
        }

        // hash arrays travrsal;
        int duplicate_element = -1;
        for(int i = 0; i<=max_; i++){
            int count = hash[i];

            if(count > 1){
                duplicate_element = i; // index itself is the duplicate_element
            }
        }
        return duplicate_element;

    }
};

```
